import io, json, os, time, urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
MODEL = 'qwen2.5:14b'
TIMEOUT = 1500
LANE = 'cpu'
CPU_THREADS = 4      # CEO 10% CPU margin law (O-20260913-2215)
GENERATE_URL = 'http://localhost:11434/api/generate'
MATERIAL = 'MC-20261014-REACT-v17 static card (cards.json + render output + e4-material.md)'
prompt = '你是一名刷公众号图文/信息流的普通读者，看到下面这张静态速报卡《城市速报 017》\n（1080×1080 方图·黑底；左上角小字「[AIGC·AI 生成内容]」；顶部大标题「城市速报 017」）。\n图上写着：\n「今日热点 · 知乎热榜 2026-10-14」；\n「如何看待Andrej Karpathy提出「AI能力认知漏斗」，少数专业人士已开始有「眩晕感」？」——这是当天知乎热榜的原题原样转写；\n「怀旧轴：『泡一杯茶，看这世界慢慢转』」；\n「求新轴：『刚画完这幅，感觉跟过去那些不一样，挺有趣的』」；\n「秩序轴：『校准了时间，才踏实过一天』」——这三行是城市 AI 居民对这个话题的三种生活情境反应；\n「归档者-07信条：『参数不收敛，天理难容。』」——最后一行是老居民归档者-07的信条收束。\n图内底部声明行「基于硅基城市真实事件（知乎热榜台账档案）」。\n背景：硅基城市是一家由 AI 全自主运转的公司集团（只有一个人类老板，其余成员全是 AI）。\n「城市速报」系列是集团旗下媒体公司出品的热点速报卡——把城市当天热议话题原样转写出来，配上 AI 居民的情境台词，不虚构不加工。\n本卡的背景是：AI 圈的 Andrej Karpathy 提出「AI 能力认知漏斗」，说大模型越强、圈外人越看不懂它到底能干什么，少数专业人士已经开始有「眩晕感」——这是当天知乎热榜热度一百六十八万的话题；\n卡上三行台词是 AI 居民的三种生活反应，最后一行是老工程师人格居民归档者-07的信条。\n请回答三个问题，每题一段，直说不委婉：\n1) 刷到这张卡你会停下来看吗？会保存或转发给朋友吗？打几分（0-10）？为什么？\n2) 有没有一眼假、空洞套话的地方？有的话扣几分、指出原句？\n3) 最弱的一项是什么？'

result = {'ts': time.strftime('%Y-%m-%d %H:%M:%S'), 'model': MODEL,
          'material': MATERIAL, 'lane': LANE}
payload = json.dumps({'model': MODEL, 'prompt': prompt, 'stream': False,
                      'options': {'num_gpu': 0,
                                  'num_thread': CPU_THREADS}}).encode('utf-8')
request = urllib.request.Request(GENERATE_URL, data=payload,
                                 headers={'Content-Type': 'application/json'})
try:
    with urllib.request.urlopen(request, timeout=TIMEOUT) as resp:
        body = json.loads(resp.read().decode('utf-8', 'replace'))
    result['verdict'] = (body.get('response') or '').strip() or \
        'EMPTY-RESPONSE'
except Exception as exc:
    text = '%s: %s' % (type(exc).__name__, exc)
    if 'timed out' in text.lower() or 'timeout' in text.lower():
        result['verdict'] = 'TIMEOUT-%ds' % TIMEOUT
    else:
        print('TRANSPORT-ERROR %s' % text, flush=True)
        raise SystemExit(3)
io.open(os.path.join(HERE, 'e4-result.json'), 'w', encoding='utf-8').write(
    json.dumps(result, ensure_ascii=False, indent=2))
print('DONE' if not result['verdict'].startswith('TIMEOUT') else 'TIMEOUT')
